data:
Workout:
  type: object
  description: One completed workout (representative shape).
  properties:
    id: { type: string }
    d: { type: string, format: date, description: 'ISO day, e.g. "2026-08-30".' }
    start: { type: number, description: ms since epoch }
    end: { type: number }
    routineId: { type: string }
    name: { type: string }
    bw: { type: number, description: 'Body weight that day, in `unit`.' }
    vol: { type: number, description: Total volume (Σ weight × reps). }
    prs:
      type: array
      items: { type: string }
      description: Exercise ids that hit a personal record.
    entries:
      type: array
      items:
        type: object
        properties:
          id: { type: string, description: Exercise id. }
          topW: { oneOf: [{ type: number }, { type: 'null' }] }
          sets:
            type: array
            items:
              type: object
              properties:
                w: { type: number, description: Weight. }
                r: { type: number, description: Reps. }
                done: { type: boolean }
                rir: { type: number }
                rpe: { type: number }
              additionalProperties: true
        additionalProperties: true
    media:
      type: array
      maxItems: 6
      items:
        $ref: '#/components/schemas/MediaRef'
      description: >-
